// Ported from Fancy Components (MIT, (c) 2024 Daniel Petho) — https://github.com/danielpetho/fancy/blob/main/src/fancy/components/physics/elastic-line.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { useDimensions } from "@/hooks/use-dimensions"
import { useElasticLineEvents } from "@/hooks/use-elastic-line-events"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

import { animate, motion, useAnimationFrame, useMotionValue, type ValueAnimationTransition } from "motion/react"
import { useEffect, useRef, useState } from "react"

export interface ElasticLineProps {
  isVertical?: boolean
  grabThreshold?: number
  releaseThreshold?: number
  strokeWidth?: number
  transition?: ValueAnimationTransition
  animateInTransition?: ValueAnimationTransition
  className?: string
}

const defaultSpring: ValueAnimationTransition = { type: "spring", stiffness: 300, damping: 5 }
const defaultEntrance: ValueAnimationTransition = { duration: 0.3, ease: "easeInOut" }

export function ElasticLine({
  isVertical = false,
  grabThreshold = 5,
  releaseThreshold = 100,
  strokeWidth = 1,
  transition = defaultSpring,
  animateInTransition = defaultEntrance,
  className,
}: ElasticLineProps) {
  const containerRef = useRef<SVGSVGElement>(null)
  const pathRef = useRef<SVGPathElement>(null)
  const dimensions = useDimensions(containerRef)
  const prefersReducedMotion = usePrefersReducedMotion()
  const motionOn = useAnimationActive(containerRef)
  const [hasAnimatedIn, setHasAnimatedIn] = useState(false)
  const clampedReleaseThreshold = Math.min(releaseThreshold, Math.max(isVertical ? dimensions.width / 2 : dimensions.height / 2, 0))
  const { isGrabbed, controlPoint } = useElasticLineEvents(containerRef, isVertical, grabThreshold, clampedReleaseThreshold)
  const x = useMotionValue(0)
  const y = useMotionValue(0)
  const pathLength = useMotionValue(prefersReducedMotion ? 1 : 0)

  useEffect(() => {
    if (dimensions.width <= 0 || dimensions.height <= 0) return
    x.set(dimensions.width / 2)
    y.set(dimensions.height / 2)
    if (prefersReducedMotion) {
      pathLength.set(1)
      queueMicrotask(() => setHasAnimatedIn(true))
      return
    }
    if (hasAnimatedIn) return
    const controls = animate(pathLength, 1, {
      ...animateInTransition,
      onComplete: () => setHasAnimatedIn(true),
    })
    return () => controls.stop()
  }, [animateInTransition, dimensions.height, dimensions.width, hasAnimatedIn, pathLength, prefersReducedMotion, x, y])

  useEffect(() => {
    if (prefersReducedMotion || !hasAnimatedIn || isGrabbed) return
    const xControls = animate(x, dimensions.width / 2, transition)
    const yControls = animate(y, dimensions.height / 2, transition)
    return () => {
      xControls.stop()
      yControls.stop()
    }
  }, [dimensions.height, dimensions.width, hasAnimatedIn, isGrabbed, prefersReducedMotion, transition, x, y])

  useAnimationFrame(() => {
    const straightX = dimensions.width / 2
    const straightY = dimensions.height / 2
    if (prefersReducedMotion || !motionOn) {
      pathRef.current?.setAttribute(
        "d",
        isVertical
          ? `M${straightX} 0Q${straightX} ${straightY} ${straightX} ${dimensions.height}`
          : `M0 ${straightY}Q${straightX} ${straightY} ${dimensions.width} ${straightY}`,
      )
      return
    }
    if (isGrabbed) {
      x.set(controlPoint.x)
      y.set(controlPoint.y)
    }
    const controlX = hasAnimatedIn ? x.get() : straightX
    const controlY = hasAnimatedIn ? y.get() : straightY
    pathRef.current?.setAttribute(
      "d",
      isVertical
        ? `M${straightX} 0Q${controlX} ${controlY} ${straightX} ${dimensions.height}`
        : `M0 ${straightY}Q${controlX} ${controlY} ${dimensions.width} ${straightY}`,
    )
  })

  return (
    <svg
      aria-hidden
      className={cn("h-full w-full", className)}
      data-reduced={prefersReducedMotion ? "true" : "false"}
      data-slot="elastic-line"
      preserveAspectRatio="none"
      ref={containerRef}
      viewBox={`0 0 ${dimensions.width} ${dimensions.height}`}
    >
      <motion.path fill="none" initial={{ pathLength: prefersReducedMotion ? 1 : 0 }} ref={pathRef} stroke="currentColor" strokeWidth={strokeWidth} style={{ pathLength }} />
    </svg>
  )
}

"use client"

import { animate, motion, useMotionValue, useTransform } from "motion/react"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface ElasticSliderProps {
  className?: string
  min?: number
  max?: number
  defaultValue?: number
  color?: string
  scale?: number
  speed?: number
}

function ElasticSlider({
  className,
  min = 0,
  max = 100,
  defaultValue = 42,
  color,
  scale,
  speed,
}: ElasticSliderProps) {
  const reduced = usePrefersReducedMotion()
  const [value, setValue] = React.useState(defaultValue)
  const trackRef = React.useRef<HTMLDivElement>(null)
  const stretch = useMotionValue(0)
  const amount = scale === undefined || scale === 1 ? 1 : scale
  const scaleX = useTransform(stretch, (latest) => {
    if (amount === 1) return 1 + Math.min(0.22, Math.abs(latest) * 0.55)
    return 1 + Math.min(0.22 * amount, Math.abs(latest) * 0.55 * amount)
  })
  const origin = useTransform(stretch, (latest) => (latest < 0 ? "right center" : "left center"))
  const thumbX = useTransform(stretch, (latest) => latest * (amount === 1 ? 42 : 42 * amount))

  const applyPointer = (clientX: number) => {
    const track = trackRef.current
    if (!track) return
    const rect = track.getBoundingClientRect()
    const ratio = rect.width === 0 ? 0 : (clientX - rect.left) / rect.width
    if (ratio < 0) {
      setValue(min)
      if (!reduced) stretch.set(ratio)
      return
    }
    if (ratio > 1) {
      setValue(max)
      if (!reduced) stretch.set(ratio - 1)
      return
    }
    stretch.set(0)
    setValue(min + ratio * (max - min))
  }

  const release = () => {
    if (reduced) {
      stretch.set(0)
      return
    }
    void animate(
      stretch,
      0,
      speed === undefined || speed === 1
        ? { type: "spring", stiffness: 460, damping: 16 }
        : { type: "spring", stiffness: 460 * speed, damping: 16 },
    )
  }

  const percent = ((value - min) / Math.max(max - min, 1)) * 100

  return (
    <div data-slot="elastic-slider" className={cn("w-full max-w-md space-y-3", className)}>
      <div className="flex items-center justify-between text-sm">
        <span>弹性滑块</span>
        <span className="tabular-nums text-muted-foreground">{Math.round(value)}</span>
      </div>
      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={Math.round(value)}
        aria-label="弹性滑块"
        className="relative h-10 cursor-ew-resize touch-none outline-none"
        onPointerDown={(event) => {
          event.currentTarget.setPointerCapture(event.pointerId)
          applyPointer(event.clientX)
        }}
        onPointerMove={(event) => {
          if (!event.currentTarget.hasPointerCapture(event.pointerId)) return
          applyPointer(event.clientX)
        }}
        onPointerUp={release}
        onPointerCancel={release}
        onKeyDown={(event) => {
          const step = (max - min) / 20
          if (event.key === "ArrowRight" || event.key === "ArrowUp") {
            setValue((current) => Math.min(max, current + step))
          }
          if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
            setValue((current) => Math.max(min, current - step))
          }
        }}
      >
        <motion.div
          className="absolute top-4 h-2 w-full rounded-full bg-muted"
          style={{ scaleX, transformOrigin: origin }}
        />
        <motion.div
          className={cn("absolute top-4 h-2 rounded-full", color ? undefined : "bg-primary")}
          style={
            color
              ? { width: `${percent}%`, scaleX, transformOrigin: origin, backgroundColor: color }
              : { width: `${percent}%`, scaleX, transformOrigin: origin }
          }
        />
        <motion.div
          className="absolute top-2.5 size-5 rounded-full border-2 border-primary bg-background shadow"
          style={{ left: `calc(${percent}% - 10px)`, x: thumbX }}
        />
      </div>
      <p className="text-xs text-muted-foreground">拖过两端会像橡皮一样拉长，松手弹回。</p>
    </div>
  )
}

export { ElasticSlider }

